#include "CollisionGeometry.h"
#include "CollisionAsset.h"
#include <iostream>
int main(){MeshData mesh;for(auto p:{glm::vec3(-10,0,-10),glm::vec3(10,0,-10),glm::vec3(10,0,10),glm::vec3(-10,0,10)}){MeshVertex v;v.position=p;mesh.vertices.push_back(v);}mesh.indices={0,2,1,0,3,2};CollisionAsset a;CollisionCookSettings settings;std::string error;if(!CookCollision(mesh,settings,a,error))return 2;PrimitivePose floor,box;floor.shape=Shape::Cooked(std::make_shared<CollisionAsset>(a),"floor");box.shape=Shape::Box({.4,.2,.3});box.parentPosition={0,.23,0};box.parentOrientation=glm::angleAxis(.3f,glm::vec3(0,0,1));auto m=CookedContacts(box,floor,.2);for(int i=0;i<m.count;++i){auto& c=m.points[i];auto R=glm::dmat3(glm::mat3_cast(box.parentOrientation));auto wa=glm::dvec3(box.parentPosition)+R*c.localWitnessA,wb=c.localWitnessB;std::cout<<"reported="<<c.signedSeparation<<" physical="<<glm::dot(c.preciseNormal,wa-wb)<<" normal="<<c.preciseNormal.y<<" a_y="<<wa.y<<'\n';}return 0;}
